CREATE TABLE IF NOT EXISTS user_credit_account (user_id varchar(64) COLLATE utf8mb4_bin PRIMARY KEY, balance decimal(18,2) NOT NULL DEFAULT 0 CHECK(balance>=0), opening_balance decimal(18,2) NOT NULL DEFAULT 0 CHECK(opening_balance>=0), status varchar(16) NOT NULL DEFAULT 'ACTIVE', version bigint NOT NULL DEFAULT 0, audit_source varchar(255) NOT NULL DEFAULT 'NEW', total_amount decimal(18,2) NOT NULL DEFAULT 0, available_amount decimal(18,2) NOT NULL DEFAULT 0, account_status varchar(16) NOT NULL DEFAULT 'open', create_time datetime DEFAULT CURRENT_TIMESTAMP, update_time datetime DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS raffle_activity_account (user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,activity_id bigint NOT NULL,total_remaining bigint NOT NULL DEFAULT 0 CHECK(total_remaining>=0),day_limit bigint NOT NULL DEFAULT 0 CHECK(day_limit>=0),month_limit bigint NOT NULL DEFAULT 0 CHECK(month_limit>=0),effective_draw_count bigint NOT NULL DEFAULT 0 CHECK(effective_draw_count>=0),version bigint NOT NULL DEFAULT 0,opening_total bigint NOT NULL DEFAULT 0,opening_day_limit bigint NOT NULL DEFAULT 0,opening_month_limit bigint NOT NULL DEFAULT 0,opening_effective_count bigint NOT NULL DEFAULT 0,audit_source varchar(255) NOT NULL DEFAULT 'NEW',PRIMARY KEY(user_id,activity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS raffle_activity_account_month (user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,activity_id bigint NOT NULL,business_month char(7) NOT NULL,quota_limit bigint NOT NULL CHECK(quota_limit>=0),remaining bigint NOT NULL CHECK(remaining>=0),opening_quota bigint NOT NULL CHECK(opening_quota>=0),audit_source varchar(255) NOT NULL DEFAULT 'NEW',PRIMARY KEY(user_id,activity_id,business_month)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS raffle_activity_account_day (user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,activity_id bigint NOT NULL,business_date date NOT NULL,quota_limit bigint NOT NULL CHECK(quota_limit>=0),remaining bigint NOT NULL CHECK(remaining>=0),opening_quota bigint NOT NULL CHECK(opening_quota>=0),effective_draw_count bigint NOT NULL DEFAULT 0 CHECK(effective_draw_count>=0),opening_effective_count bigint NOT NULL DEFAULT 0,audit_source varchar(255) NOT NULL DEFAULT 'NEW',PRIMARY KEY(user_id,activity_id,business_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS user_credit_ledger_{{suffix}} (ledger_id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,biz_type varchar(32) COLLATE utf8mb4_bin NOT NULL,biz_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,delta decimal(18,2) NOT NULL,balance_after decimal(18,2) NOT NULL CHECK(balance_after>=0),receipt json NOT NULL,UNIQUE KEY biz(user_id,biz_type,biz_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS user_request_receipt_{{suffix}} (user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,operation varchar(32) COLLATE utf8mb4_bin NOT NULL,request_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,order_id varchar(128) COLLATE utf8mb4_bin NULL,result_state varchar(32) NOT NULL,receipt json NOT NULL,PRIMARY KEY(user_id,operation,request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS user_quota_ledger_{{suffix}} (user_id varchar(64) COLLATE utf8mb4_bin NOT NULL,activity_id bigint NOT NULL,biz_type varchar(32) COLLATE utf8mb4_bin NOT NULL,biz_id varchar(128) COLLATE utf8mb4_bin NOT NULL,request_hash char(64) NOT NULL,bucket_type varchar(16) NOT NULL,bucket_key varchar(16) NOT NULL,delta bigint NOT NULL,limit_delta bigint NOT NULL,remaining_after bigint NOT NULL CHECK(remaining_after>=0),receipt json NOT NULL,PRIMARY KEY(user_id,activity_id,biz_type,biz_id,bucket_type,bucket_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
